// Get transcript segments from WayinVideo
const segments = $('4. WayinVideo — Get Transcript Results').item.json.data.transcript || [];

if (segments.length === 0) {
  throw new Error('Transcript is empty — check if the video URL is valid and publicly accessible.');
}

// Format transcript with speaker labels and timestamps
const formattedTranscript = segments
  .map(s => {
    const timeInSeconds = Math.floor(s.start / 1000);
    const minutes = Math.floor(timeInSeconds / 60);
    const seconds = timeInSeconds % 60;
    const timestamp = `${minutes}:${seconds.toString().padStart(2, '0')}`;
    return `[${s.speaker} | ${timestamp}] ${s.text.trim()}`;
  })
  .join('\n');

// Duration
const lastSegment = segments[segments.length - 1];
const totalDurationMs = lastSegment?.end || 0;
const totalMinutes = Math.round(totalDurationMs / 60000);

// Word count
const wordCount = segments.map(s => s.text).join(' ').split(/\s+/).length;

// Speakers
const speakers = [...new Set(segments.map(s => s.speaker))];

// Form data
const videoTitle = $('1. Form — Video URL + Content Details').item.json['Video / Episode Title'];
const creatorName = $('1. Form — Video URL + Content Details').item.json['Creator / Brand Name'];
const niche = $('1. Form — Video URL + Content Details').item.json['Content Niche'];
const targetAudience = $('1. Form — Video URL + Content Details').item.json['Target Audience'];
const contentTone = $('1. Form — Video URL + Content Details').item.json['Content Tone'];
const videoUrl = $('1. Form — Video URL + Content Details').item.json['Video URL'];

return [{
  json: {
    formattedTranscript,
    totalMinutes,
    wordCount,
    speakerCount: speakers.length,
    videoTitle,
    creatorName,
    niche,
    targetAudience,
    contentTone,
    videoUrl
  }
}];

// Parse AI output into structured fields
const output = $input.first().json.output || '';

// Extract Twitter thread
const twitterMatch = output.match(/TWITTER_THREAD:\s*([\s\S]*?)(?=\nTHREAD_HASHTAGS:|$)/);
const threadHashtagsMatch = output.match(/THREAD_HASHTAGS:\s*([\s\S]*?)(?=\nLINKEDIN_POST:|$)/);
const linkedinMatch = output.match(/LINKEDIN_POST:\s*([\s\S]*?)(?=\nBLOG_TITLE:|$)/);
const blogTitleMatch = output.match(/BLOG_TITLE:\s*([\s\S]*?)(?=\nBLOG_META_DESCRIPTION:|$)/);
const blogMetaMatch = output.match(/BLOG_META_DESCRIPTION:\s*([\s\S]*?)(?=\nBLOG_CONTENT:|$)/);
const blogContentMatch = output.match(/BLOG_CONTENT:\s*([\s\S]*?)(?=\nFOCUS_KEYWORD:|$)/);
const focusKeywordMatch = output.match(/FOCUS_KEYWORD:\s*([\s\S]*?)(?=\nHASHTAGS:|$)/);
const hashtagsMatch = output.match(/HASHTAGS:\s*([\s\S]*)$/);

const twitterThread = twitterMatch ? twitterMatch[1].trim() : '';
const threadHashtags = threadHashtagsMatch ? threadHashtagsMatch[1].trim() : '';
const linkedinPost = linkedinMatch ? linkedinMatch[1].trim() : '';
const blogTitle = blogTitleMatch ? blogTitleMatch[1].trim() : '';
const blogMeta = blogMetaMatch ? blogMetaMatch[1].trim() : '';
const blogContent = blogContentMatch ? blogContentMatch[1].trim() : '';
const focusKeyword = focusKeywordMatch ? focusKeywordMatch[1].trim() : '';
const hashtags = hashtagsMatch ? hashtagsMatch[1].trim() : '';

// Word counts
const twitterWordCount = twitterThread.split(/\s+/).length;
const linkedinWordCount = linkedinPost.replace(/<[^>]*>/g, ' ').split(/\s+/).filter(w => w.length > 0).length;
const blogWordCount = blogContent.replace(/<[^>]*>/g, ' ').split(/\s+/).filter(w => w.length > 0).length;

// Get video data
const videoData = $('7. Code — Format Transcript').item.json;

if (!twitterThread || !linkedinPost || !blogContent) {
  throw new Error('Could not parse one or more content pieces from AI output. Check the AI prompt output format.');
}

return [{
  json: {
    twitterThread: twitterThread + '\n\n' + threadHashtags,
    linkedinPost,
    blogTitle,
    blogMeta,
    blogContent,
    focusKeyword,
    hashtags,
    twitterWordCount,
    linkedinWordCount,
    blogWordCount,
    videoTitle: videoData.videoTitle,
    creatorName: videoData.creatorName,
    niche: videoData.niche,
    targetAudience: videoData.targetAudience,
    videoUrl: videoData.videoUrl,
    totalMinutes: videoData.totalMinutes
  }
}];
